def reachable_corner(blocked):
    seen=np.zeros((H,W),bool); q=deque()
    for r in range(H):
        for c in range(W):
            if (r in(0,H-1) or c in(0,W-1)) and not blocked[r,c]:
                q.append((r,c)); seen[r,c]=1
    while q:
        y,x=q.popleft()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and not seen[ny,nx] and not blocked[ny,nx]:
                seen[ny,nx]=1; q.append((ny,nx))
        for dy,dx in((1,1),(1,-1),(-1,1),(-1,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and not seen[ny,nx] and not blocked[ny,nx]:
                # corner rule: diagonal move blocked if either orthogonal corner is blocked
                if not blocked[y+dy,x] and not blocked[y,x+dx]:
                    seen[ny,nx]=1; q.append((ny,nx))
    return seen
