def comp_np(mask,r,c,vis):
    q=deque([(r,c)]); vis[r,c]=1; cells=[]
    while q:
        y,x=q.popleft(); cells.append((y,x))
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<mask.shape[0] and 0<=nx<mask.shape[1] and not vis[ny,nx] and mask[ny,nx]:
                vis[ny,nx]=1; q.append((ny,nx))
    return cells
