def solve(inp):
    g=inp.copy(); H,W=g.shape
    noise=set(zip(*np.where(g!=0)) ) # placeholder; noise color = non-bg? determine bg = most common
    vals,cnt=np.unique(g,return_counts=True)
    bg=vals[np.argmax(cnt)]
    for r in range(H):
        row=np.where(g[r]!=bg)[0]
        for c in range(W):
            if g[r,c]!=bg: continue
            left=row[row<c]; right=row[row>c]
            col=np.where(g[:,c]!=bg)[0]
            up=col[col<r]; dn=col[col>r]
            if (len(left) and len(right)) or (len(up) and len(dn)):
                g[r,c]=3
    return g,bg
